const dataArray = $json.data || $json.entries || [];
const out = [];

// Assignee name → DB identity mapping
const ASSIGNEE_MAP = {
  "chisty": {
    assignee_id: "242630708",  // ✅ Changed to string for consistency
    assignee_name: "Shoabur Rahman Chishty",
