    assignee_name: "Fahim",
    assignee_email: "fahim@niftyitsolution.com"
  }
};

// Helpers
const toISO = v => (v ? new Date(Number(v)).toISOString() : null);
const s = v => (v ?? '').toString();
const toNullIfEmpty = v => (v && v.toString().trim() !== '') ? v.toString() : null;

dataArray.forEach(entry => {
  const user = entry.user || {};

  // Extract tags from this specific time entry
  const tags = (entry.tags || [])
    .map(t => t.name.toLowerCase().trim())
    .filter(tag => tag in ASSIGNEE_MAP);

  // Convert tag names → mapped assignee objects
  const assignees = tags.map(tag => ASSIGNEE_MAP[tag]);

  // ========================================================================
  // CRITICAL FIX: Create ONE output item per assignee
  // ========================================================================

  if (assignees.length === 0) {
    // No assignee tags found - use the logged user as fallback
    console.log(`⚠️  No assignee tags for entry ${entry.id}, using logged user: ${user.username}`);

    out.push({
      json: {
        time_entry_id: entry.id,
        task_id: entry.task?.id || null,
        task_name: entry.task?.name || '',
        user_id: user.id?.toString() || null,
        user_name: s(user.username),
        user_email: s(user.email),
        start_time: toISO(entry.start),
        end_time: toISO(entry.end),
        duration_hours: entry.duration ? Number(entry.duration) / 3600000 : 0,
        billable: !!entry.billable,
        description: toNullIfEmpty(entry.description),
        // Metadata for debugging
        source: 'logged_user',
        original_tags: JSON.stringify(entry.tags || [])
      }
    });
  } else {
    // ✅ CREATE ONE RECORD PER ASSIGNEE
    assignees.forEach((assignee, index) => {
      console.log(`✅ Creating entry ${index + 1}/${assignees.length} for ${assignee.assignee_name}`);

      out.push({
        json: {
          // ✅ Make entry ID unique per assignee
          time_entry_id: `${entry.id}_${assignee.assignee_id}`,
          task_id: entry.task?.id || null,
          task_name: entry.task?.name || '',

          // ✅ Use mapped assignee data (not logged user)
          user_id: assignee.assignee_id,
          user_name: assignee.assignee_name,
          user_email: assignee.assignee_email,

          start_time: toISO(entry.start),
          end_time: toISO(entry.end),
          duration_hours: entry.duration ? Number(entry.duration) / 3600000 : 0,
          billable: !!entry.billable,
          description: toNullIfEmpty(entry.description),

          // Metadata for debugging
          source: 'tag_mapping',
          original_logged_user_id: user.id?.toString() || null,
          original_logged_user_name: s(user.username),
          original_tags: JSON.stringify(entry.tags || [])
        }
      });
    });
  }
});

